// An ordered set of states. NVDA iterates `sorted(states)`, so the order of
// the output follows the bit positions, and that order is user-visible.
class StateSet {
public:
    StateSet() = default;
    StateSet(std::initializer_list<State> states) {
        for (const State state : states) {
            add(state);
        }
    }

    static StateSet fromBits(std::uint64_t bits) {
        StateSet set;
        set.bits_ = bits;
        return set;
    }

    void add(State state) { bits_ |= mask(state); }
    void remove(State state) { bits_ &= ~mask(state); }
    bool has(State state) const { return (bits_ & mask(state)) != 0; }
    bool empty() const noexcept { return bits_ == 0; }
    std::size_t size() const noexcept;
    std::uint64_t bits() const noexcept { return bits_; }

    // In bit-position order.
    std::vector<State> toVector() const;

    StateSet operator|(const StateSet& other) const { return fromBits(bits_ | other.bits_); }
    StateSet operator&(const StateSet& other) const { return fromBits(bits_ & other.bits_); }
    // Set difference: what is in this set and not in the other.
    StateSet operator-(const StateSet& other) const { return fromBits(bits_ & ~other.bits_); }
    bool operator==(const StateSet& other) const noexcept { return bits_ == other.bits_; }
    bool operator!=(const StateSet& other) const noexcept { return bits_ != other.bits_; }
    bool intersects(const StateSet& other) const noexcept { return (bits_ & other.bits_) != 0; }

private:
    static std::uint64_t mask(State state) {
        return std::uint64_t{1} << static_cast<std::uint64_t>(static_cast<std::int32_t>(state));
    }

    std::uint64_t bits_ = 0;
};

